<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElButton,ElAlert,ElDialog} from 'element-plus'
import {callAdmin} from './api'
type Rule={type:string;regions:string[];price:number};type Freight={_id:string;name:string;rules:Rule[];isDefault:boolean}
const items=ref<Freight[]>([]),editor=ref(false),busy=ref(false),error=ref(''),notice=ref(''),previewId=ref(''),region=ref(''),preview=ref(''),form=ref({_id:'',name:'',isDefault:false,rules:[] as {type:string;regions:string;yuan:number}[]})
const labels:Record<string,string>={normal:'普通/地区价',extra:'偏远加价',no_delivery:'不发货'}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){items.value=(await callAdmin<{templates:Freight[]}>('freight.list')).templates;if(!items.value.some(f=>f._id===previewId.value))previewId.value=items.value[0]?._id||''}
function open(f?:Freight){form.value=f?{_id:f._id,name:f.name,isDefault:f.isDefault,rules:f.rules.map(r=>({...r,regions:r.regions.join('，'),yuan:Number(r.price)/100}))}:{_id:'',name:'',isDefault:false,rules:[{type:'normal',regions:'*',yuan:10},{type:'extra',regions:'新疆，西藏，青海，宁夏，甘肃，内蒙古',yuan:10},{type:'no_delivery',regions:'香港，澳门，台湾，港澳台',yuan:0}]};editor.value=true}
function save(){run(async()=>{await callAdmin('freight.save',{id:form.value._id||undefined,data:{name:form.value.name,isDefault:form.value.isDefault,rules:form.value.rules.map(r=>({type:r.type,regions:r.regions.split(/[,，]/).map(s=>s.trim()).filter(Boolean),price:Math.round(r.yuan*100)}))}});editor.value=false;await load();notice.value='运费模板已保存'})}
function remove(id:string){if(confirm('确认删除此未使用的模板？'))run(async()=>{await callAdmin('freight.delete',{id});await load();notice.value='模板已删除'})}
function calculate(){run(async()=>{preview.value='';const r=await callAdmin<{amount:number}>('freight.preview',{id:previewId.value,region:region.value});preview.value='该地区运费 ¥'+(Number(r.amount)/100).toFixed(2)})}
onMounted(()=>run(load))
</script>
<template><section class="content freight-manager"><div class="section-heading"><div><p class="eyebrow">SHIPPING SETTINGS</p><h1>运费模板</h1></div><ElButton @click="open()">新增运费模板</ElButton></div><ElAlert v-if="error" :title="error" type="error" :closable="false"/><ElAlert v-if="notice" :title="notice" type="success" :closable="false"/><form class="admin-form settings-card" @submit.prevent="calculate"><h3>地区运费试算</h3><label>运费模板<select v-model="previewId" aria-label="试算运费模板"><option v-for="f in items" :key="f._id" :value="f._id">{{f.name}}</option></select></label><label>收货地区<input v-model="region" aria-label="试算收货地区" required placeholder="例如新疆 乌鲁木齐"/></label><ElButton native-type="submit" :loading="busy">试算运费</ElButton><p v-if="preview" role="status">{{preview}}</p></form><article v-for="f in items" :key="f._id" class="settings-card" :data-freight-id="f._id"><h3>{{f.name}} {{f.isDefault?'· 默认':''}}</h3><p v-for="(r,i) in f.rules" :key="i">{{labels[r.type]}} · {{r.regions.join('、')}}<template v-if="r.type!=='no_delivery'"> · ¥{{(Number(r.price)/100).toFixed(2)}}</template></p><div class="action-row"><ElButton @click="open(f)">编辑模板</ElButton><ElButton @click="remove(f._id)">删除模板</ElButton></div></article>
<ElDialog v-model="editor" title="运费模板资料" width="min(720px, calc(100vw - 24px))"><ElAlert v-if="error" :title="error" type="error" :closable="false"/><form class="admin-form" @submit.prevent="save"><label>模板名称<input v-model="form.name" aria-label="运费模板名称" maxlength="120" required/></label><label class="checkbox-label"><input v-model="form.isDefault" type="checkbox" aria-label="默认运费模板"/>设为默认模板</label><div v-for="(r,i) in form.rules" :key="i" class="freight-rule"><label>规则类型<select v-model="r.type" :aria-label="'运费规则类型'+i"><option value="normal">普通/地区价</option><option value="extra">偏远加价</option><option value="no_delivery">不发货</option></select></label><label>地区（逗号分隔，*为普通地区）<input v-model="r.regions" :aria-label="'运费地区'+i" required/></label><label v-if="r.type!=='no_delivery'">金额（元）<input v-model.number="r.yuan" :aria-label="'运费金额'+i" type="number" min="0" max="1000000" step="0.01" required/></label><ElButton @click="form.rules.splice(i,1)">移除此规则</ElButton></div><p class="muted">普通地区须保留一条*价格；偏远规则为额外加价。港澳台可选“不发货”，或设独立地区价。商品与赠品可选择套模板或包邮。</p><div class="action-row"><ElButton @click="form.rules.push({type:'extra',regions:'',yuan:0})">新增地区规则</ElButton><ElButton native-type="submit" type="primary" :loading="busy">保存运费模板</ElButton></div></form></ElDialog></section></template>
<style>.freight-rule{padding:16px;background:#f3f5f9;border-radius:6px;display:grid;grid-template-columns:1fr 2fr;gap:16px}.freight-rule label{min-width:0}.freight-rule .el-button{align-self:end;justify-self:start}.freight-manager .settings-card p{overflow-wrap:anywhere}@media(max-width:768px){.freight-rule{grid-template-columns:1fr;padding:12px}.freight-manager .section-heading{flex-wrap:wrap;gap:12px}.freight-manager .section-heading h1{font-size:26px}}</style>
